    {'id': 'tip_typography_smart_quotes_and_primes', 'engine': 'typography_cleaner', 'feature': 'Smart Quotes Normalizer', 'subfeature': 'smart_quotes_normalizer', 'category': 'craft', 'pillar': 'editorial_craft', 'title': 'Smart Quotes vs Primes: Handling Leading Dialogue Elisions and Measurements', 'content': 'Never let automated typographers turn leading-elision apostrophes (e.g. ’em, ’round, ’cause) into opening single quotes (‘). Use the smart quotes normalizer to preserve right curly apostrophes (U+2019) in contractions and straight primes (′/″) for coordinates and heights.', 'rationale': 'Standard automated typography algorithms misinterpret leading apostrophes as opening quotes, violating publishing industry typesetting rules.', 'example': 'arcanum audit quotes Manuscript/ --normalize', 'tags': ['typography', 'smart-quotes', 'primes', 'typesetting', 'shunn', 'elision', 'smart-quotes-normalizer'], 'contexts': ['publishing', 'review', 'cli'], 'depth': 'advanced', 'weight': 1.0},
